suppressPackageStartupMessages({library(here);library(dplyr);library(readr);library(tibble)})
source(here("scripts","helpers.R")); source(here("scripts","load_recovery.R"))
d <- read_csv(here("data","garmin_daily.csv"),show_col_types=FALSE)
a <- read_csv(here("data","garmin_activities.csv"),show_col_types=FALSE,col_types=cols(activity_id=col_character(),start=col_datetime(),name=col_character(),type_key=col_character(),.default=col_double()))
z <- read_csv(here("data","garmin_activity_zones.csv"),show_col_types=FALSE,col_types=cols(activity_id=col_character(),.default=col_double()))
am <- merge_rides(a,30,3)|>mutate(group=activity_group(type_key))
rhr_ref <- median(d$resting_hr[d$resting_hr>=45],na.rm=T); p <- athlete_profile(rhr_ref)
as <- session_load(am,p,0.4,z); dl <- daily_load_recovery(d,as)
cat("--- unrecorded Perioden & Wear-Evidenz\n")
u <- dl|>filter(unrecorded)|>select(date,steps,resting_hr,sleep_h,hrv_night,bb_high)
print(u|>summarise(n=n(),von=min(date),bis=max(date),steps_med=median(steps,na.rm=T),sleep_med=median(sleep_h,na.rm=T),rhr_med=median(resting_hr,na.rm=T)))
r <- rle(dl$unrecorded); print(data.frame(len=r$lengths,val=r$values)[r$values,])
print(dl|>filter(unrecorded)|>select(date,steps,resting_hr,sleep_h)|>as.data.frame()|>head(32))
cat("\n--- ACWR Extremwerte\n"); print(dl|>filter(acwr<0.4|acwr>1.5)|>select(date,load,acute_d,chronic_d,acwr)|>as.data.frame())
cat("\n--- max_hr Verteilung\n"); print(table(cut(am$max_hr,c(0,170,182,190,200,250))))
print(am|>filter(max_hr>182)|>select(start,type_key,avg_hr,max_hr,duration_min)|>as.data.frame()|>head(20))
cat("\n--- merge_rides weighted.mean-Bug?\n")
t <- tibble(activity_id=c("1","2"),start=as.POSIXct(c("2026-01-01 08:00","2026-01-01 08:20"),tz="UTC"),name="x",type_key="cycling",distance_km=c(1,1),duration_min=c(10,30),avg_hr=c(100,140),max_hr=c(120,150),kcal=1,elev_gain=1,te_aerobic=1,te_anaerobic=1)
print(try(merge_rides(t,30,3)))
cat("mean-hr-of-segments erwartet gewichtet:",weighted.mean(c(100,140),c(10,30)),"\n")
cat("\n--- Heutiger Tag partial?\n"); print(tail(dl|>select(date,steps,kcal_active,sleep_h,hrv_night,load_meas,load_est,acwr),4)|>as.data.frame())
cat("\n--- Korrelation der 4 Signale (z)\n"); print(round(cor(dl[,c("rhr_z","sleep_z","bb_z","hrv_z")],use="pairwise.complete.obs"),2))
cat("\n--- sd RHR / Quantisierung\n"); rr <- dl$resting_hr[dl$resting_hr>=45]; cat("sd:",sd(rr,na.rm=T),"\n"); print(table(rr))
cat("Letzter z-Basis-sd rhr:",tail(na.omit(dl$rhr_base),1),"\n")
cat("\n--- HIIT Wochentag\n"); print(table(weekdays(dl$date[dl$hiit])))
cat("\n--- HIIT-Effekt: Autokorrelation (lag1) der Differenz-Metriken\n")
x <- dl$sleep_score; print(acf(x,plot=F,na.action=na.pass,lag.max=3)$acf[2:4])
x <- dl$hrv_night; print(acf(x,plot=F,na.action=na.pass,lag.max=3)$acf[2:4])
cat("\n--- Perm-Test: Cluster/Autokorr-robust? Block-Bootstrap CI fuer Diff Schlaf-Score\n")
rs <- recovery_summary(dl)
# Wilcoxon + Cohen d + Bonferroni
d2 <- dl|>mutate(sleep_ok=!is.na(sleep_h)&sleep_h>=5)
nx <- tibble(date=d2$date-1,ss=ifelse(d2$sleep_ok,d2$sleep_score,NA),rd=d2$ready_score,hv=ifelse(d2$sleep_ok,d2$hrv_night,NA),rh=ifelse(d2$resting_hr>=45,d2$resting_hr,NA))
xx <- d2|>filter(!unrecorded)|>select(date,hiit)|>inner_join(nx,by="date")
for(m in c("ss","rd","hv","rh")){a1<-na.omit(xx[[m]][xx$hiit]);b1<-na.omit(xx[[m]][!xx$hiit]);sp<-sqrt(((length(a1)-1)*var(a1)+(length(b1)-1)*var(b1))/(length(a1)+length(b1)-2))
 tt<-t.test(a1,b1); cat(m,"d=",round((mean(a1)-mean(b1))/sp,2)," CI95 diff:",round(tt$conf.int,2)," wilcox p=",signif(wilcox.test(a1,b1)$p.value,3),"\n")}
cat("\n--- Readiness ~ Garmin-Last (Zirkularitaet) ready vs ts_acute / recovery_h\n"); print(round(cor(dl[,c("ready_score","recovery_h","ts_acute","sleep_score","hrv_night")],use="pairwise.complete.obs"),2))
cat("\n--- TRIMP: kein-HR Rad Konstante\n"); print(summary(as$trimp[as$est]))
cat("Tageslast-Anteil est an chronic (mean):",mean(dl$load_est,na.rm=T)/mean(dl$load,na.rm=T),"\n")
# ACWR sensitivity: ohne geschaetzte Last; EWMA; uncoupled
ew <- function(x,lam){y<-numeric(length(x));y[1]<-x[1];for(i in 2:length(x))y[i]<-ifelse(is.na(x[i]),y[i-1],x[i]*lam+(1-lam)*y[i-1]);y}
l <- dl$load; l2 <- ifelse(is.na(l),0,l)
ac <- roll_apply(l,7,mean,5); ch <- roll_apply(l,28,mean,14)
dl$acwr_meas <- roll_apply(dl$load_meas,7,mean,5)/roll_apply(dl$load_meas,28,mean,14)
dl$acwr_ewma <- ew(l2,2/8)/ew(l2,2/29)
ch_unc <- roll_apply(l,21,mean,10,lag_by=7); dl$acwr_unc <- ac/ch_unc
print(round(cor(dl[,c("acwr","acwr_meas","acwr_ewma","acwr_unc")],use="pairwise.complete.obs"),2))
cat("Zeit im Band 0.8-1.3: own",mean(dl$acwr>=.8&dl$acwr<=1.3,na.rm=T)," meas-only",mean(dl$acwr_meas>=.8&dl$acwr_meas<=1.3,na.rm=T)," ewma",mean(dl$acwr_ewma>=.8&dl$acwr_ewma<=1.3,na.rm=T)," unc",mean(dl$acwr_unc>=.8&dl$acwr_unc<=1.3,na.rm=T),"\n")
cat("Tage ACWR>1.3: own",sum(dl$acwr>1.3,na.rm=T)," meas-only",sum(dl$acwr_meas>1.3,na.rm=T)," ewma",sum(dl$acwr_ewma>1.3,na.rm=T)," unc",sum(dl$acwr_unc>1.3,na.rm=T),"\n")
cat("\n--- Zonen: Zone-TRIMP vs avg-HR TRIMP gleiche Sessions\n")
cmp <- as|>filter(trimp_src=="zonen",!is.na(avg_hr))|>mutate(trimp_avg=banister(duration_min,pmin(pmax((avg_hr-p$rhr_ref)/(p$hrmax-p$rhr_ref),0),1),p$trimp_b))
print(cmp|>group_by(type_key)|>summarise(n=n(),zone=sum(trimp),avg=sum(trimp_avg),ratio=sum(trimp)/sum(trimp_avg)))
cat("\n--- Zonensumme vs Dauer\n"); zz<-as|>filter(trimp_src=="zonen");print(summary(zz$z_min/zz$duration_min))
cat("\n--- RHR ref Sensitivität\n"); for(rf in c(50,54,58)){pp<-athlete_profile(rf);ss<-session_load(am,pp,0.4,z);cat("rhr_ref",rf,"TRIMP-Summe",round(sum(ss$trimp,na.rm=T)),"\n")}
for(hm in c(172,178,182,190)){pp<-p;pp$hrmax<-hm;ss<-session_load(am,pp,0.4,z);cat("hrmax",hm,"TRIMP-Summe",round(sum(ss$trimp,na.rm=T)),"\n")}
